#define EPSILON 0.0005
#define MIN_DISTANCE 0.005
#define MAX_DISTANCE 25. 
#define PRECISION 0.001
#define MAX_STEPS 110
#define BALL_RADIUS 3.1
#define DAMPING_TIME 3.2 // how much time (seconds) a single wave will exist (thus propage)
#define WAVE_SIZE 3.2
#define WAVES_CYCLE 6.6 // full cycle of X waves
#define WAVES_DISTANCE 0.5 // time distance between subsequent waves (in  a loop)
#define WAVES_COUNT 6
#define DISTANCE_METHODS 8. // how many methods of measuring methods we do have



#define TIME_SPEED_FACTOR 28.
#define PI 3.1415926
#define TIME_LOOP 30.

struct Material {
    vec3 ambientColor;
    vec3 diffuseColor;
    vec3 specularColor;
    float alpha;
};



Material greyM() {
  vec3 aCol = vec3(1.0, .95, .95);
  vec3 dCol = vec3(.5);
  vec3 sCol = vec3(.5);
  float a = 55.;

  return Material(aCol, dCol, sCol, a);
}



Material grey;


float sdSphere(vec3 p, vec3 c, float r) {
    vec3 np = vec3(p);
    vec3 ve2 = vec3(p);
    ve2.x = np.x + sin(np.z * .4) * 1.2;
    ve2.y = np.y + sin(np.z * 0.5) * 1.3;
    ve2.z = sin(np.z * 2.) * 0.7;

    float distSphere = abs(length(ve2 - c) - r) - 0.6;

   return distSphere;
}

// source https://www.shadertoy.com/view/Xds3zN
