float scene(vec3 p) {
    int octZcorrection = int(mod(floor(iTime / 3.0), 10.0));
    float sTime = mod(iTime, TIME_LOOP);
//    float octDist = clamp(sdOctahedron(rotateZ(cos(iTime * 4.)) * rotateX(cos(iTime * 2.)) * rotateY(sin(iTime * 3.)) * (p-vec3(.6,0.15,+12.0 - iTime * 4. +3.*octZcorrection)), 0.35), 0., 0.5);
    float octDist = clamp(sdOctahedron(rotateZ(cos(sTime * 4.)) * rotateX(cos(sTime * 2.)) * rotateY(sin(sTime * 3.)) * (p-vec3(.6 - sin(float(octZcorrection)),0.15,+12.0 - sTime * 4. + 30. * float(octZcorrection))), 0.35), -3., 0.5);
    return min(sdSphere(p, vec3(0., 0., 0.), BALL_RADIUS), octDist); 
}



// vector normal to sphere with cener c and radius r
vec3 calcNormal(vec3 p) {
  vec2 e = vec2(1.02, -1.02) * EPSILON;
  return normalize(
    e.xyy * scene(p + e.xyy) +
    e.yyx * scene(p + e.yyx) +
    e.yxy * scene(p + e.yxy) +
    e.xxx * scene(p + e.xxx));
}


struct RaymarchRes {
    vec3 p; // surface hit point
    float d; // distance
};


RaymarchRes raymarch(vec3 ro, vec3 rd) {
    float t = MIN_DISTANCE; 
    RaymarchRes res;
    res.d = MAX_DISTANCE;

    for (int i = 0; i < MAX_STEPS; i++) {
        vec3 p = ro + t * rd;
        float sf = scene(p); 
        t += sf;

        if (sf < PRECISION) { // we hit the surface at point p
            res.p = p;
            res.d = sf;
            break;
        } else if (sf > MAX_DISTANCE) break; // we did not hit anything but are to far away from camera 
            //t += sf.d; // we did not hit anything, keep on trying
    }

    res.d = t;
    return res;
}

mat3 camera(vec3 cameraPos, vec3 lookAtPoint) {
    vec3 cd = normalize(lookAtPoint - cameraPos);
    vec3 cr = normalize(cross(vec3(0, 1, 0), cd));
    vec3 cu = normalize(cross(cd, cr));

    return mat3(-cr, cu, -cd);
}

vec3 calculateCameraPosition(vec3 lookAt, vec2 uv) {
    float sTime = iTime * 2.7;
//   vec3 ro = vec3(-1., -5. + sin(iTime), lookAt.z - 10.); 
//   vec3 ro = vec3(sin(iTime * 1.7) / 1.6, sin(iTime * 1.7) / 1.8, - 10.)  + vec3(0., 0., 0.2) * min(iTime, TIME_LOOP) * TIME_SPEED_FACTOR;
   vec3 ro = vec3(sin(sTime) / 1.3, sin(sTime) / 1.5, - 10.)  + vec3(0., 0., 0.2) * mod(iTime, TIME_LOOP) * TIME_SPEED_FACTOR;
   //vec3 ro = vec3(2.1 + someShapingFunction(), 0. + someShapingFunction() * 1., lookAt.z - 4. + sin(iTime) * 3.); 
   return ro;
}

vec3 calculateLightPosition(vec3 lookAt) {
    float sTime = iTime * 4.;

    vec3 lightVector = vec3(sin(sTime) + 4., sin(sTime) + 2., -18.) + vec3(0., 0., 0.2) * mod(iTime, TIME_LOOP) * TIME_SPEED_FACTOR; ;
    return lightVector;
}

vec3 wanderOnSphere(float time, float radius) {
    float azimuth = sin(time * 2.);//mod(time * WAVE_CENTER_WANDERING_SPEED * 4., 2.0 * PI) + PI * 1.5 - 0.4; 
    float elevation = sin(time * 2.) * PI;//-0.1 + sin(time * PI * 2. + cycle) / 2.;//sin(time * SPOT_LIGHT_SPEED * 0.5) * PI * 0.5;// - 0.5; 

    // change coordinates to cartesian system
    float x = radius * cos(elevation) * cos(azimuth);
    float y = radius * sin(elevation) ;
    float z = radius * cos(elevation) * sin(azimuth) - 6.;

    return vec3(x, y, z);
}



vec3 calculateLight(vec2 fragCoord, RaymarchRes rr, vec3 rd, vec3 lo, vec3 backgroundColor) {
    vec3 po = rr.p;
    vec3 normalToSurfaceVector = calcNormal(po);
    vec3 l = -normalize(-lo + po); // light direction
    Material m = grey;

    vec3 color = m.ambientColor; 


    float light = clamp(dot(normalToSurfaceVector, l), 0., 5.);
    color *= vec3(light);
    vec3 spotLight1 = vec3(1., 0., 0.);
    int distanceMethod = int(mod(mod(iTime / WAVES_CYCLE, DISTANCE_METHODS * WAVES_CYCLE), DISTANCE_METHODS));

    for (int i = 0; i <  WAVES_COUNT; i++) {
        float dTime = float(i) * WAVES_DISTANCE;
        float wCTime = mod(iTime, WAVES_CYCLE) - dTime;
        vec3 sc = wanderOnSphere(dTime, BALL_RADIUS);
        sc.z +=  mod(iTime, TIME_LOOP) * TIME_SPEED_FACTOR * 0.2;
        //float dd = pow(length(sc - po), 1.);
        float dd = length(sc - po);
        float dt = max(0., (DAMPING_TIME - wCTime)) / DAMPING_TIME;
        float d1 = wCTime; 
        float d2 = d1 + mix(WAVE_SIZE, 0., 1. -dt);


        if (dd > d1 && dd < d2) {
            vec3 targetColor = mix(color, spotLight1, clamp((DAMPING_TIME - wCTime) / DAMPING_TIME, 0., 1.));
            targetColor *= color;
            float dc = (d1 + d2) / 2.;
            color = mix(targetColor, color, smoothstep(dc, (dd <= dc ? d1 :d2), dd));
        }
    }


    color = clamp(color, 0., 1.);


    vec2 q = fragCoord.xy / iResolution.xy;
    color = vec3(color * pow(20. * q.x * q.y * (1.0 - q.x) * (1.0 - q.y), 0.5)); // vigniete
    color = mix(color, vec3(0.0,0.0,0.0), 1.0 - exp(-0.0002*rr.d*rr.d*rr.d)); // fog to black

    return color;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;

    grey = greyM();

    vec3 lookAt = vec3(0.0,0.5, 0.) + vec3(0., 0., 0.2) * iTime * TIME_SPEED_FACTOR;
    vec3 ro = calculateCameraPosition(lookAt, uv);
    vec3 rd = camera(ro, lookAt) * normalize(vec3(uv, -0.9)); 
    vec3 lo = calculateLightPosition(lookAt);

//    vec4 backgroundColor = vec4(mix(vec3(0., 0.01, .1), vec3(0., 0., 0.), uv.y) * 1.8, 1.0);
    vec4 backgroundColor = vec4(0., 0., 0., 1.0);
    RaymarchRes rr = raymarch(ro, rd);

    fragColor = (rr.d < MAX_DISTANCE) ? vec4(calculateLight(fragCoord, rr, rd, lo, backgroundColor.xyz), 1.0) : backgroundColor;    
}

mat3 rotateX(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(1, 0, 0),
        vec3(0, c, -s),
        vec3(0, s, c)
    );
}

mat3 rotateY(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(c, 0, s),
        vec3(0, 1, 0),
        vec3(-s, 0, c)
    );
}

mat3 rotateReverseY(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(c, 0, -s),
        vec3(0, 1, 0),
        vec3(s, 0, c)
    );
}


mat3 rotateZ(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(c, -s, 0),
        vec3(s, c, 0),
        vec3(0, 0, 1)
    );
}
mat3 identity() {
    return mat3(
        vec3(1, 0, 0),
        vec3(0, 1, 0),
        vec3(0, 0, 1)
    );
}
